 n=struct.unpack('>I',png[off:off+4])[0];typ=png[off+4:off+8];data=png[off+8:off+8+n];crc=struct.unpack('>I',png[off+8+n:off+12+n])[0];assert zlib.crc32(typ+data)&0xffffffff==crc
 chunks.append(typ.decode());off+=n+12
 if typ==b'IHDR':ihdr=struct.unpack('>IIBBBBB',data)
 if typ==b'IDAT':idat+=n
