assert all(len(x)==3 and all(math.isfinite(y) for y in x) for x in v)
edges=collections.defaultdict(list);links=collections.defaultdict(lambda:collections.defaultdict(set));adj=[set() for _ in ts]
for i,t in enumerate(ts):
 assert len(t)==3 and len(set(t))==3 and all(type(x)==int and 0<=x<len(v) for x in t)
 aa,bb,cc=[v[x] for x in t];ab=[bb[k]-aa[k] for k in range(3)];ac=[cc[k]-aa[k] for k in range(3)];cr=[ab[1]*ac[2]-ab[2]*ac[1],ab[2]*ac[0]-ab[0]*ac[2],ab[0]*ac[1]-ab[1]*ac[0]];assert math.hypot(*cr)>1e-10
 for k,x in enumerate(t):
  y=t[(k+1)%3];z=t[(k+2)%3];edges[tuple(sorted((x,y)))].append((i,x,y));links[x][y].add(z);links[x][z].add(y)
for es in edges.values():
 assert len(es)==2 and es[0][1]==es[1][2] and es[0][2]==es[1][1]
 aa,bb=es[0][0],es[1][0];adj[aa].add(bb);adj[bb].add(aa)
seen=set();components=0
for i in range(len(ts)):
 if i in seen:continue
 components+=1;seen.add(i);queue=[i]
 for x in queue:
  for y in adj[x]:
   if y not in seen:seen.add(y);queue.append(y)
assert components==3
for link in links.values():
 assert all(len(ns)==2 for ns in link.values());seen={next(iter(link))};queue=list(seen)
 for x in queue:
  for y in link[x]:
   if y not in seen:seen.add(y);queue.append(y)
 assert len(seen)==len(link)
old=Path('docs/evidence/appearance-2026-10-05/overshirt-first-view/export');o=json.loads((old/'mesh.json').read_text())
assert m['sourceMeshSHA256']==hashlib.sha256((old/'mesh.json').read_bytes()).hexdigest() and m['sourceOBJsha256']==hashlib.sha256((old/'overshirt.obj').read_bytes()).hexdigest()
for oi,ni in m['originalVertexMap'].items():assert v[ni]==o['positions'][int(oi)]
removed={x['oldFace'] for x in m['removedOldFaces']};assert len(removed)==32
retained={x['oldFace'] for x in owners if x['kind']=='retained'};assert retained==set(range(188))-removed
ov=[];ot=[];groups=[];mats=[];group=None;mat=None
for line in (d/'finish.obj').read_text().splitlines():
 if line.startswith('v '):ov.append(list(map(float,line[2:].split())))
 elif line.startswith('g '):group=line[2:]
 elif line.startswith('usemtl '):mat=line[7:]
 elif line.startswith('f '):ot.append([int(x)-1 for x in line[2:].split()]);groups.append(group);mats.append(mat)
